INSERT INTO hospital.departments (code, name, description, campus, floor, working_hours, phone, sort_order, is_active) VALUES ('kham-benh-tu-nguyen', 'Khoa Khám bệnh (Tự nguyện)', 'Khoa lâm sàng. Tiếp nhận khám ngoại trú khu Tự nguyện 1, 2 (CS1) và Tự nguyện (CS2). Bao gồm Đơn nguyên Khám và điều trị tự nguyện. Đặt lịch hẹn trước qua hotline/website/Zalo Mini App.', 'CS1+CS2', NULL, 'TN1/TN2 CS1: 7:00-16:30 (Thứ 2-Thứ 7), Chủ nhật theo lịch bác sĩ trực. TN CS2: 7:00-16:30.', '19001082', 1, TRUE) ON CONFLICT (code) DO NOTHING;
INSERT INTO hospital.departments (code, name, description, campus, floor, working_hours, phone, sort_order, is_active) VALUES ('kham-benh-tu-nguyen-1', 'Khu Khám bệnh Tự nguyện 1 - Cơ sở 1', 'Khu Khám bệnh Tự nguyện 1 tại CS1 (92 Trần Hưng Đạo). Từ 8 phòng khám chính + phòng tăng cường. Lịch khám công bố công khai trên trang ''Lịch làm việc của Bác sỹ''.', 'CS1', 'Tầng 1 (Khu TN1), Tầng 2 (cận lâm sàng cho TN1)', '7:00/7:30 - 16:00/16:30 (Thứ 2-Thứ 7)', NULL, 2, TRUE) ON CONFLICT (code) DO NOTHING;
INSERT INTO hospital.departments (code, name, description, campus, floor, working_hours, phone, sort_order, is_active) VALUES ('kham-benh-tu-nguyen-3', 'Khu Khám bệnh Tự nguyện 3 - Cơ sở 1', 'Khu Khám bệnh Tự nguyện 3 tại CS1. 9 phòng khám + 2 phòng tăng cường.', 'CS1', NULL, '6:30/7:30 - 16:30 (Thứ 2-Thứ 7)', NULL, 3, TRUE) ON CONFLICT (code) DO NOTHING;
INSERT INTO hospital.departments (code, name, description, campus, floor, working_hours, phone, sort_order, is_active) VALUES ('phong-kham-da-khoa-cs2', 'Phòng khám đa khoa - Cơ sở 2', 'Phòng khám đa khoa tại CS2 (695 Lạc Long Quân). Chuyên khoa: Tim mạch, Nhi khoa, Mắt, Tai mũi họng, Răng hàm mặt, Hô hấp, Cơ xương khớp, Y học cổ truyền, Phục hồi chức năng, Sản, Da liễu.', 'CS2', NULL, '7:30-16:30 (Thứ 2-Thứ 6, một số khoa nghỉ Thứ 7-CN)', '02437589090, 0961972097', 4, TRUE) ON CONFLICT (code) DO NOTHING;
